CREATE POLICY "ss own read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'screenshots' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "ss own insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'screenshots' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "ss own update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'screenshots' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "ss own delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'screenshots' AND (storage.foldername(name))[1] = auth.uid()::text);